interface Describable {
    fn describe(self) -> String
}

record User {
    name: String
}

record Wrap<T> {
    v: T
}

impl<T> Describable for Wrap<T> where T: Eq {
    fn describe(self) -> String {
        return "w"
    }
}

fn f(u: User) -> String {
    let w = Wrap { v: u }
    return w.describe()
}

